'use strict';
// Standalone admin entry: no analytics, service worker registration, or persisted credentials.
const API='https://api.github.com';
const $=id=>document.getElementById(id);
const TYPES={'album':'앨범·음원','music-show':'음악방송·무대',concert:'공연',milestone:'주요 기록',event:'행사',variety:'예능',radio:'라디오',interview:'인터뷰',news:'기사',official:'공식',etc:'기타'};
const BASES={'article-published':'기사 게시일','video-published':'영상 게시일','post-published':'게시글 작성일',broadcast:'방송일 (확인됨)',event:'행사일 (확인됨)',recording:'촬영일 (확인됨)',release:'발매일 (확인됨)'};
const MEMBERS=['남규리','김연지','이보람'];
let token='',repository='',branch='main',queue=[],index=[],drafts=new Map(),selected=new Set(),page=1,busy=false,timer=null,pending=null,session=0,messageTimer;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function safeURL(value){try{const u=new URL(value);return /^https?:$/.test(u.protocol)&&!u.username&&!u.password?u.href:'#';}catch{return '#';}}
function link(url,label){return `<a href="${esc(safeURL(url))}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`;}
function message(text){$('message').textContent=text;clearTimeout(messageTimer);messageTimer=setTimeout(()=>$('message').textContent='',15000);}
function remember(key,value){try{if(value===null)localStorage.removeItem(key);else localStorage.setItem(key,value);}catch{}}
function remembered(key){try{return localStorage.getItem(key)||'';}catch{return '';}}
async function api(path,options={}){
 const response=await fetch(API+path,{...options,cache:'no-store',credentials:'omit',redirect:'error',headers:{Accept:'application/vnd.github+json',Authorization:'Bearer '+token,'X-GitHub-Api-Version':'2022-11-28',...options.headers}});
 if(!response.ok){const e=new Error(response.status===401?'접속 키가 올바르지 않거나 만료됐습니다.':response.status===403?'접속 키 권한 또는 GitHub 사용 한도를 확인해 주세요.':response.status===404?'저장소·파일을 찾지 못했습니다. 저장소 이름과 키 권한을 확인해 주세요.':`GitHub 연결 오류 (${response.status}). 잠시 뒤 다시 시도해 주세요.`);e.status=response.status;throw e;}
 return response.status===204?null:response.json();
}
async function file(path,ref=branch){return api(`/repos/${repository}/contents/${path}?ref=${encodeURIComponent(ref)}`,{headers:{Accept:'application/vnd.github.raw+json'}});}
function lock(value){busy=value;for(const id of ['apply','ignore','collect','organize','refresh'])$(id).disabled=value;}
function draft(c){if(!drafts.has(c.id))drafts.set(c.id,{id:c.id,title:c.title,date:c.publishedDateKST,dateBasis:c.sourceKind==='youtube'?'video-published':'article-published',type:c.suggestedType in TYPES?c.suggestedType:'etc',members:(c.members||[]).filter(x=>MEMBERS.includes(x)),program:'',eventState:'',url:c.url,label:c.publisher||'원문 자료',note:'',targetId:c.recommendedTargetId||((c.relatedRecords||[]).length===1&&c.relatedRecords[0].strong?c.relatedRecords[0].id:''),mode:c.recommendedTargetId||((c.relatedRecords||[]).length===1&&c.relatedRecords[0].strong)?'link':'new'});return drafts.get(c.id);}
function options(values,current){return Object.entries(values).map(([v,l])=>`<option value="${esc(v)}" ${v===current?'selected':''}>${esc(l)}</option>`).join('');}
function input(id,field,label,value,type='text',wide=false){return `<label class="${wide?'wide':''}">${label}<input type="${type}" data-id="${id}" data-field="${field}" value="${esc(value)}" ${type==='date'?'':'maxlength="2000"'}></label>`;}
function card(c){const d=draft(c),id=esc(c.id),related=(c.relatedRecords||[]).map(r=>`<li>${link(location.origin+'/archive/?record='+encodeURIComponent(r.id),r.date+' · '+r.title)}</li>`).join('');
 return `<article class="candidate ${selected.has(c.id)?'picked':''}" data-card="${id}"><div class="candidate-header"><input type="checkbox" class="pick" data-id="${id}" ${selected.has(c.id)?'checked':''} aria-label="${esc(c.title)} 선택"><div class="candidate-content"><div class="metadata"><span class="tag">${c.sourceKind==='youtube'?'유튜브':'기사'}</span><span>${esc(c.publishedDateKST)} 게시</span><span>${esc((c.members||[]).join(' · '))}</span></div><h2>${esc(c.title)}</h2>${c.autoReason?'<p class=auto-reason>'+esc(c.autoReason)+'</p>':''}<div class="original">${link(c.url,'원문 확인')} · ${esc(c.publisher)}</div><details><summary>내용 확인·수정${d.targetId?' · 기존 기록에 연결':''}</summary><p class="muted">${esc(c.description||'원문에서 출연 내용을 확인해 주세요.')}</p>${related?'<p class="muted">연결할 기존 기록 후보</p><ul class="related">'+related+'</ul>':''}
 <label>반영 방식<select data-id="${id}" data-field="mode"><option value="new" ${d.mode!=='link'?'selected':''}>새 기록 추가</option><option value="link" ${d.mode==='link'?'selected':''}>기존 기록에 링크 추가</option></select></label>
 <div class="target" ${d.mode==='link'?'':'hidden'}><label>기존 기록 찾기<input type="search" data-id="${id}" class="target-search" placeholder="제목이나 날짜 입력"></label><label>연결할 기록<select data-id="${id}" data-field="targetId">${targetOptions('',d.targetId)}</select></label><p class="muted">선택한 기록의 날짜·제목·내용은 유지하고 출처 링크만 추가합니다.</p></div>
 <div class="new-fields" ${d.mode==='link'?'hidden':''}><div class="edit-grid">${input(id,'title','사이트에 표시할 제목',d.title,'text',true)}${input(id,'date','날짜',d.date,'date')}<label>날짜 기준<select data-id="${id}" data-field="dateBasis">${options(BASES,d.dateBasis)}</select></label><label>분류<select data-id="${id}" data-field="type">${options(TYPES,d.type)}</select></label><label>활동 상태<select data-id="${id}" data-field="eventState">${options({'':'별도 표시 없음',scheduled:'예정',completed:'진행 완료',cancelled:'취소'},d.eventState)}</select></label>${input(id,'program','방송·행사명 (선택)',d.program,'text',true)}<div class="wide"><span class="muted">관련 멤버 · 실제 출연·관련 여부를 확인해 선택하세요.</span><div class="member-box">${MEMBERS.map(m=>`<label><input type="checkbox" data-id="${id}" data-member="${m}" ${d.members.includes(m)?'checked':''}>${m}</label>`).join('')}</div></div><label class="wide">상세 설명 (선택)<textarea data-id="${id}" data-field="note" maxlength="2000">${esc(d.note)}</textarea></label></div></div>
 <div class="edit-grid">${input(id,'url','출처 링크 · 공식 원문으로 바꿀 수 있어요.',d.url,'url',true)}${input(id,'label','출처 이름',d.label,'text',true)}</div><p class="warning">활동일을 확인하지 못했다면 게시일 기준을 유지하세요. 게시일 기준 기록은 달력의 활동 일정에 넣지 않습니다.</p></details></div></div></article>`;}
function targetOptions(query,current){const q=query.trim().toLowerCase();let rows=index.filter(r=>(r.date+' '+r.title).toLowerCase().includes(q)).slice(0,60);const keep=index.find(r=>r.id===current);if(keep&&!rows.some(r=>r.id===current))rows.unshift(keep);return '<option value="">연결할 기록을 선택해 주세요</option>'+rows.map(r=>`<option value="${esc(r.id)}" ${r.id===current?'selected':''}>${esc(r.date+' · '+r.title)}</option>`).join('');}
function render(){const q=$('search').value.trim().toLowerCase(),member=$('member').value,source=$('source').value,rows=queue.filter(c=>(!$('bucket').value||(c.reviewBucket||'review')===$('bucket').value)&&(c.title+' '+c.description+' '+c.publisher).toLowerCase().includes(q)&&(!member||(c.members||[]).includes(member))&&(!source||c.sourceKind===source));const total=Math.max(1,Math.ceil(rows.length/10));page=Math.min(page,total);$('cards').innerHTML=rows.slice((page-1)*10,page*10).map(card).join('')||'<div class="panel empty">검토할 후보가 없습니다.<br><span class="muted">‘새 기록 찾기’를 누르거나 검색 조건을 바꿔 보세요.</span></div>';$('list-count').textContent=rows.length+'건 · '+page+' / '+total+' 페이지';$('pagination').innerHTML=`<button data-page="${page-1}" ${page===1?'disabled':''}>이전</button><span>${page} / ${total}</span><button data-page="${page+1}" ${page===total?'disabled':''}>다음</button>`;selection();}
function selection(){$('selected-count').textContent=selected.size+'건 선택';}
async function refresh(){const sid=session;const head=await api(`/repos/${repository}/git/ref/heads/${encodeURIComponent(branch)}`);let state,records;try{[state,records]=await Promise.all([file('state/candidates.json',head.object.sha),file('state/archive-index.json',head.object.sha)]);}catch(e){if(e.status!==404)throw e;state={candidates:[],checks:[],archiveCount:0};records=[];}if(sid!==session)return;queue=state.candidates||[];index=records;const ids=new Set(queue.map(c=>c.id));selected=new Set([...selected].filter(id=>ids.has(id)));drafts=new Map([...drafts].filter(([id])=>ids.has(id)));$('pending').innerHTML=queue.length+'<span>건</span>';$('archived').innerHTML=Number(state.archiveCount||index.length).toLocaleString()+'<span>건</span>';$('checked').textContent=state.checkedAt?'마지막 수집 · '+new Date(state.checkedAt).toLocaleString('ko-KR',{timeZone:'Asia/Seoul'})+' (한국 시간)':'아직 수집하지 않았습니다. ‘새 기록 찾기’를 눌러 주세요.';$('checks').innerHTML=(state.checks||[]).map(c=>`<div class="checks-item">${esc(c.source)} · ${esc(c.query||'')}<br>${esc({ok:'완료',error:'실패 — 다음 수집에서 재시도',not_configured:'유튜브 키 미등록'}[c.status]||c.status)} ${esc(c.reason||'')}</div>`).join('')||'<p>아직 수집 결과가 없습니다.</p>';renderAutomatic(state.automatic);render();}
$('login-form').addEventListener('submit',async e=>{e.preventDefault();const name=$('repository').value.trim();if(!/^[\w.-]+\/[\w.-]+$/.test(name)){message('저장소를 계정/저장소 형태로 입력해 주세요.');return;}token=$('token').value.trim();$('token').value='';repository=name;session++;$('connect').disabled=true;try{const [repo,user]=await Promise.all([api('/repos/'+repository),api('/user')]);if(!repo.private)throw Error('비공개 관리 저장소를 입력해 주세요. 공개 사이트 저장소와 다릅니다.');if(user.login.toLowerCase()!==repo.owner.login.toLowerCase())throw Error('관리 저장소 소유자의 접속 키로 로그인해 주세요.');branch=repo.default_branch;await api('/repos/'+repository+'/actions/workflows/manage.yml');await refresh();$('identity').textContent=user.login+' · '+repository;$('login').hidden=true;$('desk').hidden=false;remember('seeya-admin-repository',repository);const last=remembered('seeya-admin-request:'+repository);if(last){lock(true);watch(last,session,Date.now());}}catch(err){token='';message(err.message);}finally{$('connect').disabled=false;}});
$('logout').onclick=()=>{session++;clearTimeout(timer);token='';queue=[];index=[];drafts.clear();selected.clear();pending=null;lock(false);$('cards').replaceChildren();$('checks').replaceChildren();$('auto-history').replaceChildren();$('auto-history-link').replaceChildren();$('auto-counts').textContent='';$('job').replaceChildren();$('job').hidden=true;$('confirm').close();$('confirm-list').replaceChildren();$('desk').hidden=true;$('login').hidden=false;$('message').textContent='';};
$('repository').value=remembered('seeya-admin-repository')||'greffsozpkk/seeya-admin';
for(const id of ['search','member','source','bucket'])$(id).addEventListener('input',()=>{page=1;render();});
$('pagination').onclick=e=>{const b=e.target.closest('[data-page]');if(b){page=Number(b.dataset.page);render();$('search').scrollIntoView({block:'start',behavior:'smooth'});}};
$('cards').addEventListener('input',e=>{const el=e.target,id=el.dataset.id;if(!id)return;const d=drafts.get(id),article=el.closest('article');if(el.classList.contains('pick')){if(el.checked&&selected.size>=20){el.checked=false;message('한 번에 최대 20건까지 선택해 주세요.');return;}el.checked?selected.add(id):selected.delete(id);article.classList.toggle('picked',el.checked);selection();}else if(el.dataset.member){d.members=el.checked?[...new Set([...d.members,el.dataset.member])]:d.members.filter(m=>m!==el.dataset.member);}else if(el.classList.contains('target-search')){article.querySelector('[data-field=targetId]').innerHTML=targetOptions(el.value,d.targetId);}else if(el.dataset.field==='mode'){d.targetId='';d.mode=el.value;article.querySelector('.target').hidden=el.value!=='link';article.querySelector('.new-fields').hidden=el.value==='link';article.dataset.linking=el.value==='link'?'true':'false';}else if(el.dataset.field){d[el.dataset.field]=el.value;if(el.dataset.field==='dateBasis'&&el.value.endsWith('-published')){d.date=queue.find(c=>c.id===id).publishedDateKST;article.querySelector('[data-field=date]').value=d.date;}}});
function validate(d){const row=queue.find(c=>c.id===d.id);if(safeURL(d.url)==='#'||!d.label.trim())throw Error('출처 링크와 출처 이름을 확인해 주세요.');if(d.targetId)return;if(!d.title.trim()||!/^\d{4}-\d{2}-\d{2}$/.test(d.date)||!d.members.length)throw Error('선택한 기록의 제목·날짜·관련 멤버를 확인해 주세요. ‘내용 확인·수정’에서 바꿀 수 있습니다.');if(d.dateBasis.endsWith('-published')&&d.date!==row.publishedDateKST)throw Error('활동일을 입력했다면 날짜 기준도 방송일·행사일 등으로 바꿔 주세요.');}
function preview(action){try{if(busy)return;if(!selected.size)throw Error('먼저 반영하거나 제외할 기록을 선택해 주세요.');const edits=[...selected].map(id=>structuredClone(drafts.get(id)));if(action==='apply')for(const d of edits){const article=document.querySelector(`[data-card="${d.id}"]`);if(d.mode==='link'&&!d.targetId)throw Error('링크를 추가할 기존 기록을 선택해 주세요.');validate(d);}pending={action,edits};$('confirm-title').textContent=action==='apply'?'사이트에 반영할 기록 확인':'선택한 후보 제외';$('confirm-description').textContent=action==='apply'?'확인한 내용으로 저장한 뒤 자동 배포합니다. 새 기록의 멤버·날짜와 기존 기록의 중복 여부를 확인해 주세요.':'후보 목록에서 지우고 이후 검색에서도 제외합니다. 이미 공개된 아카이브 기록은 삭제하지 않습니다.';$('confirm-list').innerHTML=edits.map(d=>`<p><b>${esc(d.title)}</b><br>${action==='ignore'?'후보에서 제외':d.targetId?'기존 기록에 링크 추가 · '+esc(index.find(r=>r.id===d.targetId)?.title):esc(d.date+' · '+BASES[d.dateBasis]+' · '+d.members.join(' · '))}</p>`).join('');$('confirm-send').textContent=action==='apply'?'확인하고 반영':'확인하고 제외';$('confirm').showModal();}catch(e){message(e.message);}}
$('apply').onclick=()=>preview('apply');$('ignore').onclick=()=>preview('ignore');$('cancel').onclick=()=>$('confirm').close();
$('confirm-send').onclick=()=>{const request=pending;$('confirm').close();if(request)dispatch(request.action,request.edits);};
$('organize').onclick=()=>dispatch('organize',[]);$('collect').onclick=()=>dispatch('collect',[]);$('refresh').onclick=async()=>{try{lock(true);await refresh();message('목록을 새로 불러왔습니다.');}catch(e){message(e.message);}finally{lock(false);}};
function job(text,extra=''){$('job').hidden=false;$('job').innerHTML='<b>'+esc(text)+'</b>'+extra;}
async function dispatch(action,edits){if(busy)return;const payload=JSON.stringify(edits);if(new TextEncoder().encode(payload).length>50000){message('내용이 너무 깁니다. 선택한 기록을 나눠 반영해 주세요.');return;}lock(true);const id=crypto.randomUUID(),sid=session;remember('seeya-admin-request:'+repository,id);job('요청을 보내고 있습니다…');try{await api(`/repos/${repository}/actions/workflows/manage.yml/dispatches`,{method:'POST',body:JSON.stringify({ref:branch,inputs:{action,request_id:id,payload}}),headers:{'Content-Type':'application/json'}});if(sid===session){job(action==='collect'?'새 기록을 찾고 자동 정리하고 있습니다.':action==='organize'?'쌓인 후보를 자동 정리하고 사이트에 반영하고 있습니다.':'선택한 내용을 처리하고 있습니다.','<p>보통 몇 분 정도 걸립니다. 창을 닫아도 작업은 계속됩니다.</p>');watch(id,sid,Date.now());}}catch(e){if(sid!==session)return;job('요청 전송 여부를 확인하지 못했습니다.','<p>'+esc(e.message)+'</p><p>중복 요청을 피하려고 처리 결과를 먼저 확인합니다.</p>');watch(id,sid,Date.now());}}
async function watch(id,sid,start){if(sid!==session||!token)return;try{let result;try{result=await file('state/results/'+encodeURIComponent(id)+'.json');}catch(e){if(e.status!==404)throw e;}
 if(sid!==session)return;if(result){remember('seeya-admin-request:'+repository,null);lock(false);const extra='<p>'+esc(result.message)+'</p>'+link(result.runUrl,'작업 내역');job(result.status==='success'?(result.action==='apply'?'사이트 저장 완료':['collect','organize'].includes(result.action)?'자동 정리 완료':'선택한 후보 제외 완료'):'작업을 완료하지 못했습니다.',extra);await refresh();if(result.status==='success'&&(result.changes||[]).length>0){const button=document.createElement('button');button.textContent='사이트 배포 확인';button.onclick=()=>checkPublished(result);$('job').append(button);checkPublished(result);}return;}
 const data=await api(`/repos/${repository}/actions/workflows/manage.yml/runs?event=workflow_dispatch&per_page=30`);if(sid!==session)return;const run=(data.workflow_runs||[]).find(r=>(r.display_title||'').includes(id));if(run&&run.status==='completed'){lock(false);job('작업 결과를 저장하지 못했습니다.','<p>사이트 반영 여부가 불확실합니다. 작업 내역을 확인한 후 목록을 새로 불러와 주세요. 연결용 키 설정 또는 관리 저장소 저장 단계에서 문제가 생겼을 수 있습니다.</p>'+link(run.html_url,'작업 내역'));return;}
 if(Date.now()-start>20*60*1000){lock(false);job('아직 결과를 확인하지 못했습니다.','<p>GitHub 작업 내역을 확인해 주세요. 다시 로그인하면 이 요청의 결과를 이어서 확인합니다.</p>'+link(`https://github.com/${repository}/actions`,'작업 내역'));return;}
 }catch(e){if(sid!==session)return;message(e.message);}
 timer=setTimeout(()=>watch(id,sid,start),10000);}
async function checkPublished(result){const sid=session;try{const res=await fetch('/data/archive.json?admin-check='+Date.now(),{cache:'no-store',credentials:'omit'});if(!res.ok)throw Error();const rows=await res.json();if(sid!==session||!token)return;const visible=(result.changes||[]).every(c=>rows.some(r=>r.id===c.recordId&&[r.source,...(r.additionalSources||[])].some(s=>s.url===c.url)));const p=document.createElement('p');p.className='deployment';p.textContent=visible?'배포 확인 완료 — 실제 사이트에 선택한 출처가 표시됩니다.':'아직 사이트 배포 중입니다. 잠시 후 다시 확인해 주세요.';$('job').querySelector('.deployment')?.remove();$('job').append(p);if(!visible)$('job').append(Object.assign(document.createElement('a'),{href:'https://github.com/greffsozpkk/Seeya-nonofficial-site/actions',textContent:'사이트 배포 내역 ↗',target:'_blank',rel:'noopener noreferrer'}));}catch{if(sid===session)message('사이트 배포 상태를 확인하지 못했습니다. 잠시 후 다시 확인해 주세요.');}}

function renderAutomatic(report){
 if(!report){$('auto-counts').textContent='아직 자동 정리를 실행하지 않았습니다.';$('auto-history').replaceChildren();$('auto-history-link').replaceChildren();return;}
 const c=report.counts||{};
 $('auto-counts').textContent=`최근 정리: 중복 ${c.already||0}건 · 기존 기록에 연결 ${c.linked||0}건 · 신규 ${c.added||0}건 · 확인 필요 ${c.review||0}건 · 보류 ${c.held||0}건`;
 $('auto-history').innerHTML=(report.actions||[]).slice(0,100).map(a=>`<div class="checks-item"><b>${esc({already:'이미 등록된 자료',linked:'출처 연결',added:'새 기록'}[a.kind]||a.kind)}</b> · ${esc(a.candidateTitle||a.title)}<br>${esc(a.reason)}<br>${link(location.origin+'/archive/?record='+encodeURIComponent(a.recordId),'사이트 기록')} · ${link(a.url,'출처')}</div>`).join('')||'<p>이번에는 자동 반영한 자료가 없습니다.</p>';
 $('auto-history-link').innerHTML=report.requestId?link(`https://github.com/${repository}/blob/${encodeURIComponent(branch)}/state/automatic/${encodeURIComponent(report.requestId)}.json`,'전체 처리 기록 · 비공개 저장소'):'';
}
